SELECT pi."id", pd.id AS sku_id, pd.images_url, pi.spu_no, pd.sku_no, pd.name, pp.actual_arrival_qty, pp.arrival_state, pi.pirate_risk, pc.retail_price, pd.product_state, pd.status, pd.create_user_id, pd.create_time, pi.spec_type, ps.is_marketable, pd.process_id, pi.property, pi.name_en, pi.brand_name, pi.grade, pi.charge_name AS productChargeName, pd.first_mass_product_date, pd.plan_listing_time, pp.trial_production_qty, pp.ean, pp.delivery_cycle, pp.main_supplier, ps.year_sale_qty, ps.year_sale_amount, ps.listing_time, ps.delisting_time, pi.sales_channel, pi.category, pi.sale_method, ps.sale_state FROM product_info pi INNER JOIN product_detail pd ON pi.id = pd.product_id LEFT JOIN product_purchase pp ON pp.sku_id = pd."id" LEFT JOIN product_cost pc ON pc.sku_id = pd."id" LEFT join product_sale ps on pd.id = ps.sku_id WHERE pi.delete_state = 0
AND (pi.spu_no LIKE concat('%',#{params.no},'%') OR pd.sku_no LIKE concat('%',#{params.no},'%'))
AND pd.product_id = #{params.productId}
AND pd.is_change = #{params.isChange}
AND pd.status in
#{item}
AND pd.product_state in
#{state}
AND pi.category_id in
#{category}
AND pi.grade_id IN
#{gradeId}
AND ps.sale_state IN
#{saleState}
AND pi.brand_id IN
#{brandId}
AND pi.property_id IN
#{propertyId}
AND pi.project_charge_id IN
#{projectChargeId}
AND
string_to_array(#{chargeId},',') && string_to_array(pi.charge_id,',')
AND pd.charge_id in
#{chargeId}
AND pd.process_id in
#{processId}
AND pi.name LIKE concat('%',#{params.productName},'%')
AND pd.status IN
#{status}
AND pi.pirate_risk IN
#{pirateRisk}
AND pi.sale_method IN
#{saleMethod}
AND pp.ean LIKE concat('%',#{params.ean},'%')
AND pd.create_time >=#{params.startTime}
AND pd.create_time <= #{params.endTime}
${params.param}
ORDER BY pd.create_time DESC

SELECT pi."id", pd.id AS sku_id, pd.images_url, pi.spu_no, pd.sku_no, pd.name, pp.actual_arrival_qty, pp.arrival_state, pi.pirate_risk, pc.retail_price, pd.product_state, pd.create_user_id, pd.create_time, pi.spec_type, pd.status FROM product_info pi INNER JOIN product_detail pd ON pi.id = pd.product_id LEFT JOIN product_purchase pp ON pp.sku_id = pd."id" LEFT JOIN product_cost pc ON pc.sku_id = pd."id" WHERE pi.delete_state = 0
AND pi."name" = #{name}
AND pd.sku_no = #{skuNo}
LIMIT 1

SELECT pi.spu_no, pd.name, pi.sale_method, pi.category, pi.sell_spot, pi.function_desc, pi.usage_desc, CASE WHEN pi.pirate_risk = 1 THEN '有侵权风险' ELSE '无侵权风险' END pirate_risk, pi.materials, pi.property, pi.brand_name, pd.variant_property, pd.sku_no, pd."name" sku_name, pd.plan_listing_time, unit.name AS unit_name, pd.charge_name, pd.product_state, target_tax_cost, target_no_tax_cost, actual_tax_cost, actual_no_tax_cost, retail_price, target_gpm, actual_gpm_cny, actual_gpm_usd, year_sale_qty, year_sale_amount, month_sale_qty, month_sale_amount, ps.sale_country, listing_time, delisting_time, CASE WHEN is_finished_img = 1 THEN '是' ELSE '否' END is_finished_img, CASE WHEN is_finished_video = 1 THEN '是' ELSE '否' END is_finished_video, sale_state, product_size, gross_weight, net_weight, box_size, box_weight, box_qty, dp.value AS product_property, declare_chinese_name, declare_english_name, declare_price, customs_code, declare_element, english_material, english_usage, pp.ean, pp.plan_order_qty, pp.place_order_time, pp.plan_arrival_time, pp.moq, pp.delivery_cycle, pp.actual_arrival_time, pp.arrival_state, pp.purchase_user_id AS purchase_user, pp.main_supplier, pp.second_supplier, pp.actual_arrival_qty FROM product_info pi INNER JOIN product_detail pd ON pi.id = pd.product_id LEFT JOIN product_purchase pp ON pp.sku_id = pd."id" LEFT JOIN product_cost pc ON pc.sku_id = pd."id" LEFT JOIN product_sale ps ON ps.sku_id = pd."id" LEFT JOIN product_pack ppk ON ppk.sku_id = pd."id" LEFT JOIN product_logistics pl ON pl.sku_id = pd."id" LEFT JOIN product_unit unit ON pd.unit_id = unit.id LEFT JOIN basic_dict dp ON pl.product_property_id = dp.id WHERE pi.delete_state = 0
AND (pi.spu_no LIKE concat('%',#{params.no},'%') OR pd.sku_no LIKE concat('%',#{params.no},'%'))
AND pd.product_state in
#{state}
AND pd.id in
#{skuId}

SELECT id,sku_no AS name FROM product_detail


        id IN

            #{skuId}

SELECT pi.spu_no, pi.name AS spuName, pd.sku_no, pd.name AS skuName FROM product_detail pd LEFT JOIN product_info pi ON pi.id = pd.product_id WHERE pi.delete_state = 0
AND pd.sku_no IN
#{sku}

SELECT pd.id AS skuId, pi.id AS productId, pi.spu_no, pi.name AS spuName, pd.sku_no, pd.name AS skuName FROM product_detail pd LEFT JOIN product_info pi ON pi.id = pd.product_id WHERE pi.delete_state = 0
AND pd.id IN
#{skuId}
